        "content": "import { describe, expect, test } from \"bun:test\";\nimport { validateJson } from \"./validate-json\";\n\ndescribe(\"validateJson\", () => {\n  test(\"returns valid for a JSON object\", () => {\n    const result = validateJson('{\"name\": \"Alice\"}');\n    expect(result.valid).toBe(true);\n    expect(result.error).toBeUndefined();\n  });\n\n  test(\"returns valid for a JSON array\", () => {\n    const result = validateJson('[1, 2, 3]');\n    expect(result.valid).toBe(true);\n  });\n\n  test(\"returns valid for a single string value\", () => {\n    const result = validateJson('\"hello\"');\n    expect(result.valid).toBe(true);\n  });\n\n  test(\"returns valid for a single number value\", () => {\n    const result = validateJson(\"42\");\n    expect(result.valid).toBe(true);\n  });\n\n  test(\"returns valid for boolean and null values\", () => {\n    expect(validateJson(\"true\").valid).toBe(true);\n    expect(validateJson(\"false\").valid).toBe(true);\n    expect(validateJson(\"null\").valid).toBe(true);\n  });\n\n  test(\"returns invalid for empty input\", () => {\n    const result = validateJson(\"\");\n    expect(result.valid).toBe(false);\n    expect(result.error).toBe(\"Empty input\");\n  });\n\n  test(\"returns invalid for whitespace-only input\", () => {\n    const result = validateJson(\"   \");\n    expect(result.valid).toBe(false);\n    expect(result.error).toBe(\"Empty input\");\n  });\n\n  test(\"returns invalid for malformed JSON\", () => {\n    const result = validateJson(\"{invalid}\");\n    expect(result.valid).toBe(false);\n    expect(result.error).toBeDefined();\n  });\n\n  test(\"returns invalid for trailing commas\", () => {\n    const result = validateJson('{\"a\": 1,}');\n    expect(result.valid).toBe(false);\n    expect(result.error).toBeDefined();\n  });\n\n  test(\"returns invalid for unquoted keys\", () => {\n    const result = validateJson(\"{a: 1}\");\n    expect(result.valid).toBe(false);\n    expect(result.error).toBeDefined();\n  });\n});\n"
