        "content": "/**\n * CLI entry point for JSON validation.\n * Accepts file paths as arguments or reads from stdin.\n * Exits with code 0 if all inputs are valid, 1 if any are invalid.\n */\n\nimport {\n  validateJsonString,\n  validateJsonFile,\n  validateJsonFiles,\n  type ValidationResult,\n} from \"./json-validator\";\n\nfunction printResult(label: string, result: ValidationResult): void {\n  if (result.valid) {\n    console.log(`VALID   ${label} (${result.timing.durationMs.toFixed(2)}ms)`);\n  } else {\n    console.log(`INVALID ${label} (${result.timing.durationMs.toFixed(2)}ms)`);\n    if (result.error) {\n      const pos =\n        result.error.position !== undefined\n          ? ` at position ${result.error.position}`\n          : \"\";\n      console.log(`        Error: ${result.error.message}${pos}`);\n    }\n  }\n}\n\nasync function readStdin(): Promise<string> {\n  const chunks: Buffer[] = [];\n  for await (const chunk of Bun.stdin.stream()) {\n    chunks.push(Buffer.from(chunk));\n  }\n  return Buffer.concat(chunks).toString(\"utf-8\");\n}\n\nasync function main(): Promise<void> {\n  const args = process.argv.slice(2);\n\n  if (args.length === 0 || (args.length === 1 && args[0] === \"-\")) {\n    const input = await readStdin();\n    const result = validateJsonString(input);\n    printResult(\"<stdin>\", result);\n    process.exit(result.valid ? 0 : 1);\n  }\n\n  if (args.length === 1) {\n    const result = await validateJsonFile(args[0]);\n    printResult(args[0], result);\n    process.exit(result.valid ? 0 : 1);\n  }\n\n  const batch = await validateJsonFiles(args);\n  let allValid = true;\n\n  for (const [path, result] of Object.entries(batch.results)) {\n    printResult(path, result);\n    if (!result.valid) allValid = false;\n  }\n\n  console.log(\n    `\\nTotal: ${args.length} file(s), ${batch.totalDurationMs.toFixed(2)}ms`\n  );\n  process.exit(allValid ? 0 : 1);\n}\n\nmain();\n"
