        "content": "import { describe, expect, test, beforeAll, afterAll } from \"bun:test\";\nimport { mkdtemp, rm } from \"node:fs/promises\";\nimport { join } from \"node:path\";\nimport { tmpdir } from \"node:os\";\nimport {\n  validateJsonString,\n  validateJsonFile,\n  validateJsonFiles,\n} from \"./json-validator\";\n\ndescribe(\"validateJsonString\", () => {\n  test(\"accepts valid JSON object\", () => {\n    const result = validateJsonString('{\"key\": \"value\"}');\n    expect(result.valid).toBe(true);\n    expect(result.error).toBeUndefined();\n    expect(result.timing.durationMs).toBeGreaterThanOrEqual(0);\n  });\n\n  test(\"accepts valid JSON array\", () => {\n    const result = validateJsonString(\"[1, 2, 3]\");\n    expect(result.valid).toBe(true);\n  });\n\n  test(\"accepts valid JSON primitives\", () => {\n    expect(validateJsonString('\"hello\"').valid).toBe(true);\n    expect(validateJsonString(\"42\").valid).toBe(true);\n    expect(validateJsonString(\"true\").valid).toBe(true);\n    expect(validateJsonString(\"null\").valid).toBe(true);\n  });\n\n  test(\"rejects empty input\", () => {\n    const result = validateJsonString(\"\");\n    expect(result.valid).toBe(false);\n    expect(result.error?.message).toBe(\"Empty input\");\n  });\n\n  test(\"rejects malformed JSON with trailing comma\", () => {\n    const result = validateJsonString('{\"key\": \"value\",}');\n    expect(result.valid).toBe(false);\n    expect(result.error?.message).toBeDefined();\n  });\n\n  test(\"rejects truncated JSON\", () => {\n    const result = validateJsonString('{\"key\":');\n    expect(result.valid).toBe(false);\n    expect(result.error?.message).toBeDefined();\n  });\n\n  test(\"rejects plain text\", () => {\n    const result = validateJsonString(\"not json at all\");\n    expect(result.valid).toBe(false);\n  });\n\n  test(\"handles deeply nested JSON\", () => {\n    const depth = 100;\n    const nested = \"[\".repeat(depth) + \"1\" + \"]\".repeat(depth);\n    const result = validateJsonString(nested);\n    expect(result.valid).toBe(true);\n  });\n\n  test(\"includes timing information\", () => {\n    const result = validateJsonString(\"{}\");\n    expect(typeof result.timing.durationMs).toBe(\"number\");\n    expect(result.timing.durationMs).toBeGreaterThanOrEqual(0);\n  });\n\n  test(\"extracts error position when available\", () => {\n    const result = validateJsonString('{\"key\": value}');\n    expect(result.valid).toBe(false);\n    expect(result.error).toBeDefined();\n  });\n});\n\ndescribe(\"validateJsonFile\", () => {\n  let tempDir: string;\n\n  beforeAll(async () => {\n    tempDir = await mkdtemp(join(tmpdir(), \"json-validator-test-\"));\n  });\n\n  afterAll(async () => {\n    await rm(tempDir, { recursive: true, force: true });\n  });\n\n  test(\"validates a valid JSON file\", async () => {\n    const filePath = join(tempDir, \"valid.json\");\n    await Bun.write(filePath, '{\"name\": \"test\"}');\n    const result = await validateJsonFile(filePath);\n    expect(result.valid).toBe(true);\n    expect(result.timing.durationMs).toBeGreaterThanOrEqual(0);\n  });\n\n  test(\"rejects an invalid JSON file\", async () => {\n    const filePath = join(tempDir, \"invalid.json\");\n    await Bun.write(filePath, \"{bad json}\");\n    const result = await validateJsonFile(filePath);\n    expect(result.valid).toBe(false);\n    expect(result.error?.message).toBeDefined();\n  });\n\n  test(\"reports error for nonexistent file\", async () => {\n    const result = await validateJsonFile(join(tempDir, \"nonexistent.json\"));\n    expect(result.valid).toBe(false);\n    expect(result.error?.message).toContain(\"File not found\");\n  });\n\n  test(\"rejects empty file\", async () => {\n    const filePath = join(tempDir, \"empty.json\");\n    await Bun.write(filePath, \"\");\n    const result = await validateJsonFile(filePath);\n    expect(result.valid).toBe(false);\n    expect(result.error?.message).toBe(\"Empty file\");\n  });\n\n  test(\"validates large JSON file\", async () => {\n    const filePath = join(tempDir, \"large.json\");\n    const largeArray = Array.from({ length: 10000 }, (_, i) => ({\n      id: i,\n      value: `item-${i}`,\n    }));\n    await Bun.write(filePath, JSON.stringify(largeArray));\n    const result = await validateJsonFile(filePath);\n    expect(result.valid).toBe(true);\n  });\n});\n\ndescribe(\"validateJsonFiles\", () => {\n  let tempDir: string;\n\n  beforeAll(async () => {\n    tempDir = await mkdtemp(join(tmpdir(), \"json-validator-batch-\"));\n    await Bun.write(join(tempDir, \"a.json\"), '{\"a\": 1}');\n    await Bun.write(join(tempDir, \"b.json\"), '{\"b\": 2}');\n    await Bun.write(join(tempDir, \"c.json\"), \"not json\");\n  });\n\n  afterAll(async () => {\n    await rm(tempDir, { recursive: true, force: true });\n  });\n\n  test(\"validates multiple files in batch\", async () => {\n    const paths = [\n      join(tempDir, \"a.json\"),\n      join(tempDir, \"b.json\"),\n      join(tempDir, \"c.json\"),\n    ];\n    const batch = await validateJsonFiles(paths);\n\n    expect(batch.results[paths[0]].valid).toBe(true);\n    expect(batch.results[paths[1]].valid).toBe(true);\n    expect(batch.results[paths[2]].valid).toBe(false);\n    expect(batch.totalDurationMs).toBeGreaterThanOrEqual(0);\n  });\n\n  test(\"returns empty results for empty paths array\", async () => {\n    const batch = await validateJsonFiles([]);\n    expect(Object.keys(batch.results).length).toBe(0);\n    expect(batch.totalDurationMs).toBeGreaterThanOrEqual(0);\n  });\n});\n"
