t result = validateJsonString(nested);\n    expect(result.valid).toBe(true);\n  });\n\n  test(\"includes timing information\", () => {\n    const result = validateJsonString(\"{}\");\n    expect(typeof result.timing.durationMs).toBe(\"number\");\n    expect(result.timing.durationMs).toBeGreaterThanOrEqual(0);\n  });\n\n  test(\"extracts error position when available\", () => {\n    const result = validateJsonString('{\"key\": value}');\n    expect(result.valid).toBe(false);\n    expect(result.error).toBeDefined();\n  });\n});\n\ndescribe(\"validateJsonFile\", () => {\n  let tempDir: string;\n\n  beforeAll(async () => {\n    tempDir = await mkdtemp(join(tmpdir(), \"json-validator-test-\"));\n  });\n\n  afterAll(async () => {\n    await rm(tempDir, { recursive: true, force: true });\n  });\n\n  test(\"validates a valid JSON file\", async () => {\n    const filePath = join(tempDir, \"valid.json\");\n    await Bun.write(filePath, '{\"name\": \"test\"}');\n    const result = await validateJsonFile(filePath);\n    expect(result.valid).toBe(true);\n    expect(result.timing.durationMs).toBeGreaterThanOrEqual(0);\n  });\n\n  test(\"rejects an invalid JSON file\", async () => {\n    const filePath = join(tempDir, \"invalid.json\");\n    await Bun.write(filePath, \"{bad json}\");\n    const result = await validateJsonFile(filePath);\n    expect(result.valid).toBe(false);\n    expect(result.error?.message).toBeDefined();\n  });\n\n  test(\"reports error for nonexistent file\", async () => {\n    const result = await validateJsonFile(join(tempDir, \"nonexistent.json\"));\n    expect(result.valid).toBe(false);\n    expect(result.error?.message).toContain(\"File not found\");\n  });\n\n  test(\"rejects empty file\", async () => {\n    const filePath = join(tempDir, \"empty.json\");\n    await Bun.write(filePath, \"\");\n    const result = await validateJsonFile(filePath);\n    expect(result.valid).toBe(false);\n    expect(result.error?.message).toBe(\"Empty file\");\n  });\n\n  te