/**
 * High-performance JSON validation module using Bun-native APIs.
 * Provides programmatic validation for JSON strings and files with
 * detailed error reporting and performance timing.
 */

export interface ValidationError {
  message: string;
  position?: number;
}

export interface ValidationResult {
  valid: boolean;
  error?: ValidationError;
  timing: {
    durationMs: number;
  };
}

export interface BatchValidationResult {
  results: Record<string, ValidationResult>;
  totalDurationMs: number;
}

/**
 * Extract structured error details from a JSON.parse SyntaxError.
 * Attempts to parse the position/offset from the native error message.
 */
function extractParseError(err: unknown): ValidationError {
  if (err instanceof SyntaxError) {
    const message = err.message;
    const positionMatch = message.match(/position\s+(\d+)/i);
    const position = positionMatch ? Number(positionMatch[1]) : undefined;
    return { message, position };
  }
  return { message: String(err) };
}

/**
 * Validate a JSON string. Returns immediately on first error (early-exit).
 * Uses native JSON.parse for maximum performance.
 */
export function validateJsonString(input: string): ValidationResult {
  const start = performance.now();

  if (input.length === 0) {
    const durationMs = performance.now() - start;
    return {
      valid: false,
      error: { message: "Empty input" },
      timing: { durationMs },
    };
  }

  try {
    JSON.parse(input);
    const durationMs = performance.now() - start;
    return { valid: true, timing: { durationMs } };
  } catch (err) {
    const durationMs = performance.now() - start;
    return {
      valid: false,
      error: extractParseError(err),
      timing: { durationMs },
    };
  }
}

/**
 * Validate a JSON file using Bun.file() for zero-copy file reads.
 * Leverages Bun's optimized I/O for maximum throughput.
 */
export async function validateJsonFile(path: string): Promise<ValidationResult> {
  const start = performance.now();

  try {
    const file = Bun.file(path);
    const exists = await file.exists();

    if (!exists) {
      const durationMs = performance.now() - start;
      return {
        valid: false,
        error: { message: `File not found: ${path}` },
        timing: { durationMs },
      };
    }

    const text = await file.text();
    const parseStart = performance.now();

    if (text.length === 0) {
      const durationMs = performance.now() - start;
      return {
        valid: false,
        error: { message: "Empty file" },
        timing: { durationMs },
      };
    }

    try {
      JSON.parse(text);
      const durationMs = performance.now() - start;
      return { valid: true, timing: { durationMs } };
    } catch (err) {
      const durationMs = performance.now() - start;
      return {
        valid: false,
        error: extractParseError(err),
        timing: { durationMs },
      };
    }
  } catch (err) {
    const durationMs = performance.now() - start;
    return {
      valid: false,
      error: { message: `Failed to read file: ${String(err)}` },
      timing: { durationMs },
    };
  }
}

/**
 * Validate multiple JSON files in batch. Processes all files and
 * aggregates results with total timing.
 */
export async function validateJsonFiles(
